(* [comment removed for export] *)
Definition z4s1_dctx (RNG : footprint) (mm : amem) (SPF DT4 DBL DBH DST dcap tl : Z) : Prop :=
  unpoisoned mm DBL DBH /\ DBL <= DT4 /\ DT4 + 4 * 2^tl <= DBH /\ unpoisoned mm DST (DST + dcap) /\
  rng RNG DT4 (4 * 2^tl) /\ rng RNG DST dcap /\ rng RNG SPF 576 /\ rng_aimg RNG /\
  rng RNG (shad DBL) (shlen (DBH - DBL + 7)) /\ rng RNG (shad DST) (shlen (dcap + 7)) /\
  DBL mod 8 = 0 /\ DST mod 8 = 0 /\
  0x60d000 <= DT4 /\ DT4 + 16384 <= 2^47 /\ 0x60d000 <= DST /\ DST + dcap <= 2^47 /\
  0x10007fff8000 <= SPF /\ SPF + 576 <= 2^47 /\ 0x60d000 <= DBL /\ DBH <= 2^47 /\
  KXGoM.apart DST dcap 0x7fff8000 17592186044416 /\ KXGoM.apart DST dcap DT4 (4 * 2^tl) /\ KXGoM.apart DST dcap SPF 576 /\
  KXGoM.apart DT4 (4 * 2^tl) SPF 576.

Ltac z4s1_dctx_intro C :=
  destruct C as (UT & UT1 & UT2 & UD & WT & WD & WF & WI & WTS & WDS & A8a & A8b & R1 & R2 & R3 & R4 & R5 & R6 & R7 & R8 &
                 AB & AT & AF & ATF).

(* [comment removed for export] *)
Ltac kxr_ev := lazymatch goal with
  | |- _ <= bv_unsigned (ev ?E ?j) <= _ => let H := fresh "HR" in kx_range (EVar j) H; exact H
  end.

(* [comment removed for export] *)
Ltac kxr_idx tl := lazymatch goal with
  | |- 0 <= bv_unsigned (edenot ?E (EAlu ALU_SRL ?x ?s)) < 2 ^ tl =>
      apply kx_srl_tl; [ unfold E;
        lazymatch goal with
        | |- edenot (kx_env (map (Z_to_bv 64) ?zv) ?xs) _ = _ =>
            change (kx_env (map (Z_to_bv 64) zv) xs) with (kE zv xs);
            let na := eval vm_compute in (length zv) in
            rewrite (ez_ok zv (kE zv xs) (kE_atom zv xs)); cbv [ez]; change (length zv) with na;
            cbv [nth Nat.ltb Nat.leb]; f_equal; lia
        end
      | lia ]
  end.
